function createCatalog(entries: Array<readonly [string, string]>): ReadonlyMap<string, string> {
  return new Map(
    entries.map(([english, localized]) => [english.toLocaleLowerCase('en-US'), localized]),
  );
}

export const RECENT_UI_TEXT: Record<RecentUiLanguage, ReadonlyMap<string, string>> = {
  ja: createCatalog(JAPANESE_RECENT_UI_TEXT),
  'zh-CN': createCatalog(CHINESE_RECENT_UI_TEXT),
  ko: createCatalog(KOREAN_RECENT_UI_TEXT),
  de: createCatalog(GERMAN_RECENT_UI_TEXT),
};
